CREATE TABLE IF NOT EXISTS campaigns ( id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Agreed', loc TEXT NOT NULL DEFAULT '[]', deal TEXT, retarget TEXT, start_date TEXT, end_date TEXT, notes TEXT, rotation TEXT, deleted INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_campaigns_deleted ON campaigns(deleted);
